CREATE TABLE `crawler_browser_runs` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`crawler_profile_id` CHAR(36) CHARACTER SET ascii NOT NULL,`requested_by` CHAR(36) CHARACTER SET ascii NOT NULL,`status` ENUM('running','succeeded','blocked','failed','timed_out','cancelled') NOT NULL,`page_count` INT UNSIGNED NOT NULL DEFAULT 0,`item_count` INT UNSIGNED NOT NULL DEFAULT 0,`detail_count` INT UNSIGNED NOT NULL DEFAULT 0,`duration_ms` INT UNSIGNED NULL,`error_code` VARCHAR(80) CHARACTER SET ascii NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`started_at` DATETIME(3) NOT NULL,`finished_at` DATETIME(3) NULL,PRIMARY KEY (`id`),KEY `idx_crawler_run_scope_time` (`organization_id`,`workspace_id`,`started_at`),KEY `idx_crawler_run_status_time` (`status`,`started_at`),KEY `idx_crawler_run_trace` (`trace_id`),CONSTRAINT `fk_crawler_run_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),CONSTRAINT `fk_crawler_run_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspaces` (`id`),CONSTRAINT `fk_crawler_run_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`),CONSTRAINT `fk_crawler_run_profile` FOREIGN KEY (`crawler_profile_id`) REFERENCES `crawler_profiles` (`id`),CONSTRAINT `fk_crawler_run_requester` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `crawler_profile_leases` (`crawler_profile_id` CHAR(36) CHARACTER SET ascii NOT NULL,`run_id` CHAR(36) CHARACTER SET ascii NOT NULL,`lease_id` CHAR(36) CHARACTER SET ascii NOT NULL,`lease_owner` VARCHAR(160) CHARACTER SET ascii NOT NULL,`lease_token_hash` BINARY(32) NOT NULL,`leased_at` DATETIME(3) NOT NULL,`heartbeat_at` DATETIME(3) NOT NULL,`expires_at` DATETIME(3) NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,PRIMARY KEY (`crawler_profile_id`),UNIQUE KEY `uq_crawler_profile_lease_id` (`lease_id`),UNIQUE KEY `uq_crawler_profile_lease_run` (`run_id`),KEY `idx_crawler_profile_lease_expiry` (`expires_at`),CONSTRAINT `fk_crawler_profile_lease_profile` FOREIGN KEY (`crawler_profile_id`) REFERENCES `crawler_profiles` (`id`) ON DELETE CASCADE,CONSTRAINT `fk_crawler_profile_lease_run` FOREIGN KEY (`run_id`) REFERENCES `crawler_browser_runs` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `crawler_profile_lease_events` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`crawler_profile_id` CHAR(36) CHARACTER SET ascii NOT NULL,`run_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`action` ENUM('acquired','heartbeat','released','recovered') NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`occurred_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),KEY `idx_crawler_lease_event_profile_time` (`crawler_profile_id`,`occurred_at`),KEY `idx_crawler_lease_event_trace` (`trace_id`),CONSTRAINT `fk_crawler_lease_event_profile` FOREIGN KEY (`crawler_profile_id`) REFERENCES `crawler_profiles` (`id`),CONSTRAINT `fk_crawler_lease_event_run` FOREIGN KEY (`run_id`) REFERENCES `crawler_browser_runs` (`id`),CONSTRAINT `fk_crawler_lease_event_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),CONSTRAINT `fk_crawler_lease_event_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspaces` (`id`),CONSTRAINT `fk_crawler_lease_event_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `crawler_browser_run_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route` VARCHAR(200) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(255) CHARACTER SET ascii NOT NULL,`run_id` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_crawler_browser_operation` (`actor_id`,`route`,`idempotency_key`),CONSTRAINT `fk_crawler_browser_operation_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`),CONSTRAINT `fk_crawler_browser_operation_run` FOREIGN KEY (`run_id`) REFERENCES `crawler_browser_runs` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `crawler_runtime_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route` VARCHAR(200) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(255) CHARACTER SET ascii NOT NULL,`result_json` JSON NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_crawler_runtime_operation` (`actor_id`,`route`,`idempotency_key`),KEY `idx_crawler_runtime_operation_trace` (`trace_id`),CONSTRAINT `fk_crawler_runtime_operation_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
